using Avalonia.Controls;
using Avalonia.Platform;

namespace Markdownia.Services;

/// <summary>The window icon. The artwork is generated by <c>tools/IconGen</c>, which also writes the Linux and Windows icons.</summary>
public static class AppIcon
{
    public static WindowIcon? Create()
    {
        try
        {
            using var stream = AssetLoader.Open(new Uri("avares://Markdownia/Assets/Icon/markdownia.png"));
            return new WindowIcon(stream);
        }
        catch (Exception)
        {
            return null;
        }
    }
}
